/*
 * A025661  Exponent of 6 (value of i) in n-th number of form 6^i*8^j.
 * https://oeis.org/A025661
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = exponent of 6 in the n‑th smallest number of the form 6^i
 *            * 8^j. The sequence is generated by repeatedly extracting the
 *            smallest product from a min‑heap and inserting its two
 *            successors
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define MAXD     600        /* sufficient for n up to 10 000 */
#define HEAP_CAP 20005      /* enough for 2 * 10 000 + a few extra */

static bool visited[MAXD][MAXD];

typedef struct {
    idx_t i;
    idx_t j;
    double val;            /* log2(6^i * 8^j) = i + 3*j + i*log2(3) */
} Node;

static Node heap[HEAP_CAP];
static int heap_size;

seq_t a(idx_t n)
{
    if (n == 0) return 0;                   /* undefined but harmless */

    const double LOG2_3 = 1.584962500721156; /* log2(3) */

    /* Reset visited map */
    memset(visited, 0, sizeof visited);

    /* Initialise heap with the smallest element (0,0) */
    heap_size = 0;
    heap[heap_size++] = (Node){0, 0, 0.0};
    visited[0][0] = true;

    seq_t result = 0;

    for (idx_t count = 1; count <= n; ++count) {
        /* Extract minimum */
        Node cur = heap[0];
        result = cur.i;                 /* exponent of 6 for this number */

        /* Replace root with last element and heap‑down */
        heap[0] = heap[--heap_size];
        int idx = 0;
        while (1) {
            int left  = idx * 2 + 1;
            int right = left + 1;
            int smallest = idx;
            if (left < heap_size && heap[left].val < heap[smallest].val)
                smallest = left;
            if (right < heap_size && heap[right].val < heap[smallest].val)
                smallest = right;
            if (smallest == idx) break;
            Node tmp = heap[idx];
            heap[idx] = heap[smallest];
            heap[smallest] = tmp;
            idx = smallest;
        }

        if (count == n) break;          /* result already set */

        /* Child (i+1, j) */
        idx_t ni = cur.i + 1;
        idx_t nj = cur.j;
        int ii = (int)ni, jj = (int)nj;
        if (ii < MAXD && !visited[ii][jj]) {
            visited[ii][jj] = true;
            double v = (double)ii + 3.0 * jj + (double)ii * LOG2_3;
            int pos = heap_size++;
            heap[pos] = (Node){ii, jj, v};
            while (pos > 0) {
                int parent = (pos - 1) >> 1;
                if (heap[parent].val <= heap[pos].val) break;
                Node tmp = heap[parent];
                heap[parent] = heap[pos];
                heap[pos] = tmp;
                pos = parent;
            }
        }

        /* Child (i, j+1) */
        ni = cur.i;
        nj = cur.j + 1;
        ii = (int)ni; jj = (int)nj;
        if (jj < MAXD && !visited[ii][jj]) {
            visited[ii][jj] = true;
            double v = (double)ii + 3.0 * jj + (double)ii * LOG2_3;
            int pos = heap_size++;
            heap[pos] = (Node){ii, jj, v};
            while (pos > 0) {
                int parent = (pos - 1) >> 1;
                if (heap[parent].val <= heap[pos].val) break;
                Node tmp = heap[parent];
                heap[parent] = heap[pos];
                heap[pos] = tmp;
                pos = parent;
            }
        }
    }

    return result;
}
